use std::{fs, path::Path};
fn replace_once(source:&mut String,from:&str,to:&str,label:&str){let count=source.matches(from).count();assert_eq!(count,1,"compact meter patch {label} expected one match, found {count}");*source=source.replacen(from,to,1);}
fn replace_between(source:&mut String,start:&str,end:&str,replacement:&str,label:&str){let sc=source.matches(start).count();assert_eq!(sc,1,"compact meter patch {label} start expected one match, found {sc}");let begin=source.find(start).expect("compact meter start anchor");let finish=source[begin..].find(end).map(|o|begin+o).expect("compact meter end anchor");source.replace_range(begin..finish,replacement);}
pub fn run(out:&Path){let path=out.join("feature_overlays_v170_fixed.rs");let mut source=fs::read_to_string(&path).expect("read generated feature overlay").replace("\r\n","\n");
replace_between(&mut source,r#"unsafe fn on_click(hwnd:HWND,state:&mut State,lparam:LPARAM){"#,r#"fn wheel_row_steps"#,r#"unsafe fn on_click(hwnd:HWND,state:&mut State,lparam:LPARAM){
crate::ui::SetFocus(hwnd);if state.collapsed{expand_state(hwnd,state);return;}let x=physical_to_logical(lo_signed(lparam),state.scale_percent);let y=physical_to_logical(hi_signed(lparam),state.scale_percent);let rc=logical_client_rect(hwnd,state.scale_percent);
if y<TOOLBAR_H{let button=if state.kind==Kind::Dps{dps_toolbar_button_w(rc.right,dps_layout_scale(state))}else{BUTTON_W};if state.kind==Kind::Dps&&state.compact_mode{if x>=rc.right-button{PostMessageW(state.main_hwnd,0x0111,CMD_HIDE_DPS as usize,0);return;}let mode=compact_mode_rect();if x>=mode.left&&x<mode.right{show_sort_mode_menu(hwnd,state);refresh_view_detail(state);clamp_scroll(hwnd,state);InvalidateRect(hwnd,null(),0);return;}for item in toolbar_items(state,rc.right){if x>=item.rect.left&&x<item.rect.right{dispatch_toolbar_action(hwnd,state,item.action);refresh_view_detail(state);clamp_scroll(hwnd,state);InvalidateRect(hwnd,null(),0);return;}}drag_window(hwnd);return;}
if x>=rc.right-button{PostMessageW(state.main_hwnd,0x0111,if state.kind==Kind::Dps{CMD_HIDE_DPS as usize}else{CMD_HIDE_MECHANICS as usize},0);}else if x>=rc.right-button*2{collapse(hwnd,state);}else if x>=rc.right-button*3{open_feature_settings(hwnd,state);}else if state.kind==Kind::Dps{for item in toolbar_items(state,rc.right){if x>=item.rect.left&&x<item.rect.right{dispatch_toolbar_action(hwnd,state,item.action);refresh_view_detail(state);clamp_scroll(hwnd,state);InvalidateRect(hwnd,null(),0);return;}}drag_window(hwnd);}else{drag_window(hwnd);}return;}
if state.kind==Kind::Dps&&y<dps_rows_top_for(state){if !state.compact_mode{let tabs_top=TOOLBAR_H+35;if y>=tabs_top&&y<tabs_top+23{match x{8..=78=>state.sort_mode=SortMode::Damage,83..=148=>state.sort_mode=SortMode::Heal,153..=218=>state.sort_mode=SortMode::Tank,_=>{}}state.scroll=0;refresh_view_detail(state);clamp_scroll(hwnd,state);InvalidateRect(hwnd,null(),0);}}return;}if state.kind==Kind::Dps{if let Some(row)=if raid_active(state){raid_row_at(hwnd,state,x,y)}else{dps_row_at(hwnd,state,y)}{open_detail(hwnd,state,row);}}
}
"#,"semantic click");
replace_between(&mut source,r#"unsafe fn paint_toolbar(hdc:HDC,rc:RECT,state:&State){"#,r#"unsafe fn paint_toolbar_action"#,r#"unsafe fn paint_toolbar(hdc:HDC,rc:RECT,state:&State){
    let toolbar=RECT{left:0,top:0,right:rc.right,bottom:TOOLBAR_H};fill(hdc,&toolbar,crate::ui_theme::RAISED);fill(hdc,&RECT{left:0,top:TOOLBAR_H-2,right:rc.right,bottom:TOOLBAR_H},crate::ui_theme::ACCENT);let scale=dps_layout_scale(state);let button=if state.kind==Kind::Dps{dps_toolbar_button_w(rc.right,scale)}else{BUTTON_W};let items=if state.kind==Kind::Dps{toolbar_items(state,rc.right)}else{Vec::new()};let action_left=items.first().map(|item|item.rect.left-4).unwrap_or(rc.right-button*toolbar_system_count(state)-5);let old_font=if state.kind==Kind::Dps{SelectObject(hdc,dps_primary_font(state))}else{null_mut()};
    if state.kind==Kind::Dps&&state.compact_mode{let mode=compact_mode_rect();fill(hdc,&mode,crate::ui_theme::SURFACE);SetTextColor(hdc,crate::ui_theme::TEXT);draw(hdc,&format!("{} ▾",compact_mode_label(state.sort_mode)),mode,DT_CENTER|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX|DT_END_ELLIPSIS);let context_left=mode.right+6;let context_right=action_left.max(context_left);let room=context_right-context_left;if room>52{let snap=view_snapshot(state);let timer=format_time(snap.encounter_ms);let text=if room>180{let name=target_title(snap);format!("{}   {}",name,timer)}else{timer};SetTextColor(hdc,crate::ui_theme::TEXT_SECONDARY);draw(hdc,&text,RECT{left:context_left,top:0,right:context_right,bottom:TOOLBAR_H},DT_CENTER|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX|DT_END_ELLIPSIS);}}
    else{SetTextColor(hdc,crate::ui_theme::TEXT);draw(hdc,&toolbar_title(state),RECT{left:10,top:0,right:action_left.max(48),bottom:TOOLBAR_H},DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX|DT_END_ELLIPSIS);}
    for item in &items{let active=toolbar_action_active(state,item.action);let hovered=state.hover_y<TOOLBAR_H&&state.hover_x>=item.rect.left&&state.hover_x<item.rect.right;paint_toolbar_action(hdc,item.rect,item.label,active,hovered);}
    if state.kind==Kind::Dps&&state.compact_mode{let hide=RECT{left:rc.right-button,top:2,right:rc.right,bottom:TOOLBAR_H-2};let hovered=state.hover_y<TOOLBAR_H&&state.hover_x>=hide.left&&state.hover_x<hide.right;fill(hdc,&hide,if hovered{crate::ui_theme::SURFACE_HOVER}else{crate::ui_theme::SURFACE});SetTextColor(hdc,crate::ui_theme::TEXT);draw_toolbar_symbol(hdc,"×",hide,dps_adaptive_logical_px(HIDE_ICON_PX,scale));}
    else{let gear=RECT{left:rc.right-button*3,top:2,right:rc.right-button*2,bottom:TOOLBAR_H-2};let collapse=RECT{left:rc.right-button*2,top:2,right:rc.right-button,bottom:TOOLBAR_H-2};let hide=RECT{left:rc.right-button,top:2,right:rc.right,bottom:TOOLBAR_H-2};for r in [&gear,&collapse,&hide]{let hovered=state.hover_y<TOOLBAR_H&&state.hover_x>=r.left&&state.hover_x<r.right;fill(hdc,r,if hovered{crate::ui_theme::SURFACE_HOVER}else{crate::ui_theme::SURFACE});}SetTextColor(hdc,crate::ui_theme::TEXT);let icon_scale=if state.kind==Kind::Dps{dps_adaptive_logical_px(COMBAT_ICON_PX,scale)}else{COMBAT_ICON_PX};let hide_scale=if state.kind==Kind::Dps{dps_adaptive_logical_px(HIDE_ICON_PX,scale)}else{HIDE_ICON_PX};draw_toolbar_symbol(hdc,"⚙",gear,icon_scale);draw_toolbar_symbol(hdc,collapse_glyph(state),collapse,icon_scale);draw_toolbar_symbol(hdc,"×",hide,hide_scale);}if !old_font.is_null(){SelectObject(hdc,old_font);}
}
"#,"semantic toolbar paint");
replace_once(&mut source,r#"unsafe fn paint_mechanics(hdc:HDC,rc:RECT,state:&State){"#,r#"
fn dps_compact_row_h(scale:i32)->i32{dps_adaptive_logical_px(24,scale)}
fn dps_rows_top_for(state:&State)->i32{if state.kind==Kind::Dps&&state.compact_mode{TOOLBAR_H+2}else{dps_rows_top()}}
fn dps_row_h_for(state:&State,scale:i32)->i32{if state.kind==Kind::Dps&&state.compact_mode{dps_compact_row_h(scale)}else{dps_row_h(scale)}}
fn visible_dps_rows_scaled_for(state:&State,bottom:i32,scale:i32)->usize{((bottom-dps_rows_top_for(state))/dps_row_h_for(state,scale)).max(0)as usize}
fn compact_dead_status(row:&DpsRow,now:i64)->(String,u32){if row.revive_blocked_until_ms<0{return("DEAD".into(),crate::ui_theme::CRITICAL);}if row.revive_blocked_until_ms>now{return("REVIVE".into(),rgb(255,190,70));}("CAN REVIVE".into(),rgb(72,226,116))}
unsafe fn paint_compact_player(hdc:HDC,state:&State,row:&DpsRow,rank:usize,r:RECT,show_total:bool){let class_bg=spec_color(row);let bg=if row.is_dead{dim_color(crate::ui_theme::CRITICAL,48)}else{class_bg};fill(hdc,&r,bg);if row.is_local{outline(hdc,r,rgb(212,175,55),1);}let base=text_on(bg);let scale=dps_layout_scale(state);let rank_w=dps_adaptive_logical_px(24,scale);let rate_w=dps_adaptive_logical_px(64,scale);let total_w=if show_total{dps_adaptive_logical_px(70,scale)}else{0};let status_w=if row.is_dead{dps_adaptive_logical_px(76,scale)}else{0};let gap=dps_adaptive_logical_px(3,scale);let right=r.right-4;let status_left=right-status_w;let rate_right=if status_w>0{status_left-gap}else{right};let rate_left=rate_right-rate_w;let total_right=rate_left-gap;let total_left=total_right-total_w;let name_right=(if total_w>0{total_left}else{rate_left}-gap).max(r.left+rank_w+36);SelectObject(hdc,dps_secondary_font(state));SetTextColor(hdc,if row.is_local{crate::ui_theme::CRITICAL}else{crate::ui_theme::RANK_TEXT});draw(hdc,&rank.to_string(),RECT{left:r.left+3,top:r.top,right:r.left+rank_w,bottom:r.bottom},DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX);SelectObject(hdc,dps_primary_font(state));SetTextColor(hdc,if row.is_dead{rgb(255,135,135)}else{base});draw(hdc,&row.name,RECT{left:r.left+rank_w,top:r.top,right:name_right,bottom:r.bottom},DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX|DT_END_ELLIPSIS);let rate=active_rate(row,state.sort_mode);SetTextColor(hdc,if rate<=0.0{crate::ui_theme::MUTED}else{base});draw(hdc,&compact(rate),RECT{left:rate_left,top:r.top,right:rate_right,bottom:r.bottom},DT_RIGHT|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX);if total_w>0{let total=mode_metric(row,state.sort_mode);SetTextColor(hdc,if total==0{crate::ui_theme::MUTED}else{base});draw(hdc,&compact(total as f64),RECT{left:total_left,top:r.top,right:total_right,bottom:r.bottom},DT_RIGHT|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX);}if status_w>0{let(status,color)=compact_dead_status(row,now_ms());SetTextColor(hdc,color);draw(hdc,&status,RECT{left:status_left,top:r.top,right:right,bottom:r.bottom},DT_RIGHT|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX|DT_END_ELLIPSIS);}}
unsafe fn paint_compact_rows(hdc:HDC,rc:RECT,state:&State){let rows=meter_rows(state);let top=dps_rows_top_for(state);let scale=dps_layout_scale(state);let row_h=dps_compact_row_h(scale);let visible=visible_dps_rows_scaled_for(state,rc.bottom,scale);if rows.is_empty(){SetTextColor(hdc,crate::ui_theme::MUTED);draw(hdc,if state.history_index.is_some(){"No rows match the current meter filters."}else{"Waiting for party / combat data..."},RECT{left:10,top:top+12,right:rc.right-10,bottom:top+48},DT_CENTER|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX);return;}let shown=meter_page_rows(state,visible);let show_total=dps_effective_width(rc.right,scale)>=460;for(screen_i,(rank,row))in shown.iter().enumerate(){let y=top+screen_i as i32*row_h;let r=RECT{left:6,top:y,right:rc.right-8,bottom:(y+row_h-1).min(rc.bottom)};paint_compact_player(hdc,state,row,*rank,r,show_total);}}
unsafe fn paint_compact_raid_rows(hdc:HDC,rc:RECT,state:&State){let rows=meter_rows(state);let top=dps_rows_top_for(state);let scale=dps_layout_scale(state);let row_h=dps_compact_row_h(scale);if rows.is_empty(){SetTextColor(hdc,crate::ui_theme::MUTED);draw(hdc,"Waiting for raid / combat data...",RECT{left:10,top:top+12,right:rc.right-10,bottom:top+48},DT_CENTER|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX);return;}let mid=rc.right/2;let gap=dps_adaptive_logical_px(9,scale).max(7);let left=RECT{left:6,top,right:(mid-gap).max(145),bottom:rc.bottom};let right=RECT{left:(mid+gap).min(rc.right-145),top,right:rc.right-8,bottom:rc.bottom};fill(hdc,&RECT{left:mid,top:top+2,right:mid+1,bottom:(top+RAID_ROWS_PER_COLUMN as i32*row_h).min(rc.bottom)},crate::ui_theme::RAISED);let show_total=dps_effective_width((left.right-left.left).max(1),scale)>=420;for slot in 0..RAID_ROWS_PER_COLUMN{let y=top+slot as i32*row_h;if y>=rc.bottom{break;}let bottom=(y+row_h-1).min(rc.bottom);if let Some(row)=rows.get(slot){paint_compact_player(hdc,state,row,slot+1,RECT{left:left.left,top:y,right:left.right,bottom},show_total);}let ri=slot+RAID_ROWS_PER_COLUMN;if let Some(row)=rows.get(ri){paint_compact_player(hdc,state,row,ri+1,RECT{left:right.left,top:y,right:right.right,bottom},show_total);}}}
unsafe fn paint_mechanics(hdc:HDC,rc:RECT,state:&State){"#,"compact row painters");
fs::write(path,source).expect("write compact meter generated overlay");}
